package main

import (
	"fmt"
)

func dayToInt(s string) int {
	switch s[0] {
	case 'm':
		return 1
	case 't':
		if len(s) > 1 && s[1] == 'u' {
			return 2
		}
		return 4
	case 'w':
		return 3
	case 'f':
		return 5
	case 's':
		if len(s) > 1 && s[1] == 'a' {
			return 6
		}
		return 7
	}
	return 0
}

func main() {
	var s, s1 string
	fmt.Scan(&s, &s1)

	a := dayToInt(s)
	b := dayToInt(s1)

	k := a - b
	l := b - a

	if l == 0 || l == 2 || l == 3 || k == 4 || k == 5 {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

